\label{lem:private}
Let $S$ be a dominating set of $G$. Then $S$ is minimal if and only if every
$u\in S$ has a private neighbour.

\label{lem:delta1}
Every vertex of a graph lies in a minimal dominating set; hence
$\delta_d\ge1$.

\label{cor:pmean-special}
Under the notation of Theorem~\ref{thm:pmean}, the bound takes the following
forms for special values of \(p\):
\begin{align*}
p = -\tfrac{2}{3}:&\quad DRMS(G) \ge m^{-1/2} \Bigl(\sum_{e} x_e^{-2/3}\Bigr)^{3/2}, \\
p = -\tfrac{1}{2}:&\quad DRMS(G) \ge \frac{{}^{m}SO_d(G)^2}{m}, \\
p = 0:&\quad DRMS(G) \ge m \Bigl(\prod_{e} x_e\Bigr)^{-1/m}, \\
p = \tfrac{1}{2}:&\quad DRMS(G) \ge \frac{m^3}{SO_d(G)^2}, \\
p = 1:&\quad DRMS(G) \ge \frac{m^2}{DF^*(G)}.
\end{align*}

\label{prop:star}
For every \(n \ge 2\), \[DRMS(S_n) = \dfrac{n-1}{2}.\]
where \(S_n = K_{1, n-1}\) denotes the star on \(n\) vertices.

\label{lem:wheel}
Let $n\ge 4$. For every $S\subseteq V(C_{n-1})$, the following are equivalent:
\begin{enumerate}
\item $S$ is a minimal dominating set of $W_n$ with $v_0\notin S$;
\item $S$ is a minimal dominating set of $C_{n-1}$.
\end{enumerate}

\label{thm:wheel}
For $n\ge 4$,
\[
DRMS(W_n)
=(n-1)\left[
\frac{1}{1+t_{n-1}^2}
+\frac{1}{2t_{n-1}^2}
\right].
\]
